const wirePoints = [
    new THREE.Vector3(-6, 0, 0),
    new THREE.Vector3(-3, 0, 0),
    new THREE.Vector3(-1.5, 2, 0),
    new THREE.Vector3(1.5, 2, 0),
    new THREE.Vector3(3, 0, 0),
    new THREE.Vector3(6, 0, 0),
    new THREE.Vector3(6, -4, 0),
    new THREE.Vector3(-6, -4, 0),
    new THREE.Vector3(-6, 0, 0)
];

const curve = new THREE.CatmullRomCurve3(wirePoints);
curve.curveType = 'catmullrom';
curve.tension = 0.5;

const wireMaterial = new THREE.MeshStandardMaterial({
    color: 0x666666,
    metalness: 0.9,
    roughness: 0.1
});

const electronMaterial = new THREE.MeshBasicMaterial({
    color: 0x00ffff
});

const nucleusMaterial = new THREE.MeshStandardMaterial({
    color: 0xff3333,
    roughness: 0.4
});

const tubeGeometry = new THREE.TubeGeometry(curve, 100, 0.25, 8, true);
const wire = new THREE.Mesh(tubeGeometry, wireMaterial);
scene.add(wire);

const batteryGroup = new THREE.Group();
batteryGroup.position.set(-6, -2, 0);
scene.add(batteryGroup);

const batteryGeo = new THREE.BoxGeometry(1.5, 3, 1);
const batteryMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
const battery = new THREE.Mesh(batteryGeo, batteryMat);
batteryGroup.add(battery);

const posTerminal = new THREE.Mesh(
    new THREE.CylinderGeometry(0.3, 0.3, 0.4, 16),
    new THREE.MeshStandardMaterial({ color: 0xff0000, emissive: 0xff0000, emissiveIntensity: 0.3 })
);
posTerminal.position.set(0, 1.7, 0);
batteryGroup.add(posTerminal);

const negTerminal = new THREE.Mesh(
    new THREE.CylinderGeometry(0.3, 0.3, 0.4, 16),
    new THREE.MeshStandardMaterial({ color: 0x0000ff, emissive: 0x0000ff, emissiveIntensity: 0.3 })
);
negTerminal.position.set(0, -1.7, 0);
batteryGroup.add(negTerminal);

function createLabel(text, color, yPos) {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    canvas.width = 256;
    canvas.height = 128;
    ctx.fillStyle = color;
    ctx.font = 'bold 80px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, 128, 64);
    const texture = new THREE.CanvasTexture(canvas);
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: texture }));
    sprite.scale.set(1.5, 0.75, 1);
    sprite.position.y = yPos;
    return sprite;
}

batteryGroup.add(createLabel('+', '#ff0000', 2.8));
batteryGroup.add(createLabel('-', '#4444ff', -2.8));

const atoms = [];
const atomCount = 12;
for (let i = 0; i < atomCount; i++) {
    const t = i / atomCount;
    const pos = curve.getPointAt(t);

    const atomGroup = new THREE.Group();
    atomGroup.position.copy(pos);

    const nucleus = new THREE.Mesh(
        new THREE.SphereGeometry(0.35, 16, 16),
        nucleusMaterial
    );
    atomGroup.add(nucleus);

    for (let j = 0; j < 5; j++) {
        const particle = new THREE.Mesh(
            new THREE.SphereGeometry(0.12, 8, 8),
            new THREE.MeshStandardMaterial({ 
                color: j % 2 === 0 ? 0xff0000 : 0x888888 
            })
        );
        particle.position.set(
            (Math.random() - 0.5) * 0.4,
            (Math.random() - 0.5) * 0.4,
            (Math.random() - 0.5) * 0.4
        );
        atomGroup.add(particle);
    }

    scene.add(atomGroup);
    atoms.push(atomGroup);
}

const electronCount = 25;
const electrons = [];
for (let i = 0; i < electronCount; i++) {
    const geometry = new THREE.SphereGeometry(0.12, 16, 16);
    const electron = new THREE.Mesh(geometry, electronMaterial);

    const glow = new THREE.PointLight(0x00ffff, 1.5, 2);
    electron.add(glow);

    const initialT = i / electronCount;
    electrons.push({
        mesh: electron,
        t: initialT,
        speed: 0.0015,
        phase: Math.random() * Math.PI * 2
    });

    scene.add(electron);
}

const arrows = [];
for (let i = 0; i < 16; i++) {
    const t = i / 16;
    const pos = curve.getPointAt(t);
    const tangent = curve.getTangentAt(t);

    const arrow = new THREE.ArrowHelper(
        tangent.normalize(),
        pos,
        0.6,
        0xffaa00,
        0.25,
        0.15
    );
    scene.add(arrow);
    arrows.push({ mesh: arrow, t: t });
}

const ambientLight = new THREE.AmbientLight(0x404040, 1.5);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 1);
dirLight.position.set(5, 8, 5);
scene.add(dirLight);

let time = 0;

function animate() {
    requestAnimationFrame(animate);
    time += 0.016;

    electrons.forEach((elec, idx) => {
        elec.t += elec.speed;
        if (elec.t > 1) elec.t -= 1;

        const pos = curve.getPointAt(elec.t);
        const tangent = curve.getTangentAt(elec.t);

        const normal = new THREE.Vector3(0, 1, 0).cross(tangent).normalize();
        const binormal = new THREE.Vector3().crossVectors(tangent, normal).normalize();

        const radius = 0.35;
        const angle = time * 2 + elec.phase;
        const offset = normal.clone().multiplyScalar(Math.cos(angle) * radius)
            .add(binormal.clone().multiplyScalar(Math.sin(angle) * radius));

        elec.mesh.position.copy(pos).add(offset);

        const light = elec.mesh.children[0];
        light.intensity = 1 + Math.sin(time * 4 + idx) * 0.5;
    });

    arrows.forEach((arrow, idx) => {
        const brightness = 0.5 + 0.5 * Math.sin(time * 3 - idx * 0.4);
        arrow.mesh.setColor(new THREE.Color(1, 0.6 * brightness, 0));
    });

    atoms.forEach(atom => {
        atom.rotation.y += 0.02;
        atom.rotation.z += 0.01;
    });

    renderer.render(scene, camera);
}

animate();

camera.position.set(0, 6, 12);
camera.lookAt(0, -1, 0);

